import math

def cosine(x, y):
    if len(x) != len(y):
        raise ValueError('dimension mismatch')
    dot = sum(a * b for a, b in zip(x, y))
    nx = math.sqrt(sum(a * a for a in x))
    ny = math.sqrt(sum(b * b for b in y))
    if nx == 0.0 or ny == 0.0:
        return 0.0          # 零向量没有方向，约定返回 0
    return dot / (nx * ny)

print(round(cosine([1, 0, 1], [1, 1, 0]), 3))   # 0.5

def mean(xs):
    if not xs:
        raise ValueError('empty sample')
    return sum(xs) / len(xs)

def variance(xs, ddof=1):
    m = mean(xs)
    if len(xs) - ddof <= 0:
        raise ValueError('need more samples')
    return sum((x - m) ** 2 for x in xs) / (len(xs) - ddof)

data = [1, 2, 3, 4, 100]
print('mean    :', mean(data))
print('variance:', round(variance(data), 2))

def fast(s):
    n = len(s)
    if n == 0:
        return 0
    result, a = 1, 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            a += 1
        else:
            a += i + 1
        result += a
    return result

def runs(t):
    return 1 + sum(1 for i in range(1, len(t)) if t[i] != t[i - 1])

def brute(s):
    return sum(runs(s[l:r]) for l in range(len(s)) for r in range(l + 1, len(s) + 1))

for s in ['aa', 'ab', 'aba', 'aab', 'abc']:
    print(s, fast(s), brute(s))
